class Solution {

    public int longestCommonSubstr(String s1, String s2) {
        int n = s1.length(),
            m = s2.length(),
            best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int k = 0;
                while (
                        i + k < n &&
                        j + k < m &&
                        s1.charAt(i + k) == s2.charAt(j + k)
                    )
                    k++;
                best = Math.max(best, k);
            }
        }
        return best;
    }
