class Solution {

    public int longestPalindromeSubseq(String s) {
        return f(s, 0, s.length() - 1);
    }

    private int f(String s, int i, int j) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (s.charAt(i) == s.charAt(j)) return 2 + f(s, i + 1, j - 1); // both ends used
        return Math.max(f(s, i + 1, j), f(s, i, j - 1));
    }
}

