class Solution {

    public String longestPalindrome(String s) {
        int n = s.length(),
            start = 0,
            len = 1;
        boolean[][] dp = new boolean[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                // length 1..3 only needs the ends to match
                dp[i][j] =
                    s.charAt(i) == s.charAt(j) &&
                    (j - i < 3 || dp[i + 1][j - 1]);
                if (dp[i][j] && j - i + 1 > len) {
                    start = i;
                    len = j - i + 1;
                }
            }
        }
        return s.substring(start, start + len);
    }
}

