var longestPalindrome = function (s) {
    const expand = (l, r) => {
        while (l >= 0 && r < s.length && s[l] === s[r]) {
            l--;
            r++;
        }
        return r - l - 1;
    };
    let start = 0,
        len = 0;
    for (let i = 0; i < s.length; i++) {
        const cur = Math.max(expand(i, i), expand(i, i + 1));
        if (cur > len) {
            len = cur;
            start = i - Math.floor((cur - 1) / 2);
        }
    }
    return s.substring(start, start + len);
};

