class Solution {

    public int numDistinct(String s, String t) {
        return f(s, t, 0, 0);
    }

    private int f(String s, String t, int i, int j) {
        if (j == t.length()) return 1; // formed all of t
        if (i == s.length()) return 0;
        int ways = f(s, t, i + 1, j); // skip s[i]
        if (s.charAt(i) == t.charAt(j)) ways += f(s, t, i + 1, j + 1); // use s[i]
        return ways;
    }
}

