        m = t.length;
    const f = (i, j) => {
        if (j === m) return 1;
        if (i === n) return 0;
        let ways = f(i + 1, j);
        if (s[i] === t[j]) ways += f(i + 1, j + 1);
        return ways;
    };

    return f(0, 0);
};

