class Solution {

    public int numDistinct(String s, String t) {
        int n = s.length(),
            m = t.length();
        int[] dp = new int[m + 1];
        dp[0] = 1; // empty t can always be formed
        for (int i = 1; i <= n; i++) {
            for (int j = m; j >= 1; j--) {
                // right-to-left keeps dp[j-1] from the previous row
                if (s.charAt(i - 1) == t.charAt(j - 1)) dp[j] += dp[
                    j - 1
                ];
            }
        }
        return dp[m];
    }
}

