class Solution {

    public boolean isInterleave(String s1, String s2, String s3) {
        if (s1.length() + s2.length() != s3.length()) return false;
        return f(s1, s2, s3, 0, 0);
    }

    private boolean f(String a, String b, String c, int i, int j) {
        if (i == a.length() && j == b.length()) return true;
        int k = i + j; // next index in s3
        if (
            i < a.length() &&
            a.charAt(i) == c.charAt(k) &&
            f(a, b, c, i + 1, j)
        ) return true;
        return (
            j < b.length() &&
            b.charAt(j) == c.charAt(k) &&
            f(a, b, c, i, j + 1)
        );
    }
}

