            const fromS1 =
                i > 0 && dp[j] && s1[i - 1] === s3[i + j - 1];
            const fromS2 =
                j > 0 && dp[j - 1] && s2[j - 1] === s3[i + j - 1];
            dp[j] = fromS1 || fromS2;
        }
    }
    return dp[m];
};

