class Solution {

    public boolean isMatch(String s, String p) {
        return f(s, p, 0, 0);
    }

    private boolean f(String s, String p, int i, int j) {
        if (j == p.length()) return i == s.length();
        if (p.charAt(j) == '*') {
            return (
                f(s, p, i, j + 1) || // '*' matches empty
                (i < s.length() && f(s, p, i + 1, j))
            ); // '*' eats s[i]
        }
        return (
            i < s.length() &&
            (p.charAt(j) == '?' || p.charAt(j) == s.charAt(i)) &&
            f(s, p, i + 1, j + 1)
        );
    }
}

