class Solution {

    public boolean isMatch(String s, String p) {
        int n = s.length(),
            m = p.length();
        boolean[] next = new boolean[m + 1],
            cur = new boolean[m + 1];
        for (int i = n; i >= 0; i--) {
            cur[m] = i == n; // empty pattern matches only empty string
            for (int j = m - 1; j >= 0; j--) {
                char pc = p.charAt(j);
                if (pc == '*') cur[j] =
                    cur[j + 1] || (i < n && next[j]);
                else cur[j] =
                    i < n &&
                    (pc == '?' || pc == s.charAt(i)) &&
                    next[j + 1];
            }
            boolean[] tmp = next;
            next = cur;
            cur = tmp;
        }
        return next[0];
    }
}

