        return f(prices, 0, 1);
    }

    private int f(int[] p, int i, int canBuy) {
        if (i >= p.length) return 0;
        if (canBuy == 1) return Math.max(
            -p[i] + f(p, i + 1, 0),
            f(p, i + 1, 1)
        );
        return Math.max(p[i] + f(p, i + 2, 1), f(p, i + 1, 0)); // sell -> skip a day
    }
}

