class Solution {

    public int maxProfit(int[] prices) {
        int hold = -prices[0],
            sold = 0,
            rest = 0;
        for (int i = 1; i < prices.length; i++) {
            int p = prices[i];
            int newHold = Math.max(hold, rest - p); // can only buy after resting
            int newSold = hold + p; // sell what we held
            int newRest = Math.max(rest, sold); // yesterday's sale -> today's cooldown
            hold = newHold;
            sold = newSold;
            rest = newRest;
        }
        return Math.max(sold, rest);
    }
}

