class Solution {

    public int maxProfit(int[] prices, int fee) {
        int cash = 0,
            hold = -prices[0];
        for (int i = 1; i < prices.length; i++) {
            cash = Math.max(cash, hold + prices[i] - fee); // sell today (pay fee)
            hold = Math.max(hold, cash - prices[i]); // buy today
        }
        return cash;
    }
}

