var maxProfit = function (k, prices) {
    const n = prices.length;
    const memo = Array.from({ length: n }, () => [
        new Array(k + 1).fill(-1),
        new Array(k + 1).fill(-1),
    ]);
    const f = (i, canBuy, cap) => {
        if (i === n || cap === 0) return 0;
        if (memo[i][canBuy][cap] !== -1) return memo[i][canBuy][cap];
        const ans = canBuy
            ? Math.max(-prices[i] + f(i + 1, 0, cap), f(i + 1, 1, cap))
            : Math.max(
                  prices[i] + f(i + 1, 1, cap - 1),
                  f(i + 1, 0, cap),
              );
        return (memo[i][canBuy][cap] = ans);
    };
    return f(0, 1, k);
};

