class Solution {

    public int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (k >= n / 2) {
            // effectively unlimited transactions
            int profit = 0;
            for (int i = 1; i < n; i++) profit += Math.max(
                0,
                prices[i] - prices[i - 1]
            );
            return profit;
        }
        int[] buy = new int[k + 1],
            sell = new int[k + 1];
        Arrays.fill(buy, Integer.MIN_VALUE);
        for (int p : prices) {
            for (int t = 1; t <= k; t++) {
                buy[t] = Math.max(buy[t], sell[t - 1] - p); // t-th buy funded by t-1 sells
                sell[t] = Math.max(sell[t], buy[t] + p); // buy[t] >= -p here, so no overflow
            }
        }
        return sell[k];
    }
}

