    private int f(int[] a, int i, int prev) {
        if (i == a.length) return 0;
        int best = f(a, i + 1, prev); // skip
        if (prev == -1 || a[i] > a[prev]) best = Math.max(
            best,
            1 + f(a, i + 1, i)
        ); // take
        return best;
    }
