class Solution {

    public int lengthOfLIS(int[] nums) {
        int[] tails = new int[nums.length];
        int len = 0;
        for (int x : nums) {
            int lo = 0,
                hi = len; // lower bound: first tail >= x
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] < x) lo = mid + 1;
                else hi = mid;
            }
            tails[lo] = x; // replace with a smaller tail, or append
            if (lo == len) len++;
        }
        return len;
    }
}

