class Solution {

    private int maxLen = 0,
        count = 0;

    public int findNumberOfLIS(int[] nums) {
        for (int i = 0; i < nums.length; i++) dfs(nums, i, 1);
        return count;
    }

    private void dfs(int[] a, int i, int len) {
        if (len > maxLen) {
            maxLen = len;
            count = 1;
        }
        // new best length
        else if (len == maxLen) count++;
        for (int j = i + 1; j < a.length; j++) {
            if (a[j] > a[i]) dfs(a, j, len + 1);
        }
    }
}

