class Solution {

    public int matrixMultiplication(int[] arr) {
        return f(arr, 1, arr.length - 1);
    }

    private int f(int[] arr, int i, int j) {
        if (i == j) return 0; // one matrix, no multiplication
        int best = Integer.MAX_VALUE;
        for (int k = i; k < j; k++) {
            int cost =
                f(arr, i, k) +
                f(arr, k + 1, j) +
                arr[i - 1] * arr[k] * arr[j];
            best = Math.min(best, cost);
        }
        return best;
    }
}

