class Solution {

    public int matrixMultiplication(int[] arr) {
        int n = arr.length;
        int[][] dp = new int[n][n]; // dp[i][i] = 0 by default
        for (int i = n - 1; i >= 1; i--) {
            for (int j = i + 1; j < n; j++) {
                int best = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    best = Math.min(
                        best,
                        dp[i][k] +
                            dp[k + 1][j] +
                            arr[i - 1] * arr[k] * arr[j]
                    );
                }
                dp[i][j] = best;
            }
        }
        return dp[1][n - 1];
    }
}

