class Solution {

    public int maxCoins(int[] nums) {
        int n = nums.length;
        int[] a = new int[n + 2];
        a[0] = a[n + 1] = 1;
        for (int i = 0; i < n; i++) a[i + 1] = nums[i];
        return f(a, 1, n);
    }

    private int f(int[] a, int i, int j) {
        if (i > j) return 0;
        int best = 0;
        for (int k = i; k <= j; k++) {
            // k is the LAST balloon burst in [i, j]
            int coins =
                a[i - 1] * a[k] * a[j + 1] +
                f(a, i, k - 1) +
                f(a, k + 1, j);
            best = Math.max(best, coins);
        }
        return best;
    }
}

